def para(t,sty='B'): return Paragraph(t,s[sty])
def bullets(xs): return [para('&#8226; '+x,'Bulletx') for x in xs]
def table(rows,widths):
    d=[]
    for i,row in enumerate(rows): d.append([para(str(x),'HeadCell' if i==0 else 'Cell') for x in row])
    t=Table(d,colWidths=widths,repeatRows=1,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),N),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,P]),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#D9DEE6')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return t
