story += [Spacer(1,20*mm),cover,Spacer(1,12*mm),para('How to use this guide','H2x'),para('Sections 1-7 explain the product and implementation. Sections 8-10 prepare the pitch and live demo. Sections 11-12 give technical backup and a final revision sheet. Claims are grounded in the repository as it exists today. Demo data is seeded example data, not customer or market evidence.'),PageBreak()]
story += [para('Contents','H1x')]+bullets(['1. Executive overview','2. Product and feature guide','3. Architecture, data and security boundaries','4. Source code map','5. End-to-end request flows','6. AI, privacy and automation','7. Evidence and limitations','8. Slide-by-slide speaker script','9. Safe live demo plan','10. Judge Q&A: 30 grounded answers','11. Technical backup and validation','12. Last-minute revision sheet'])+[para('Claim discipline','H2x'),para('Do not claim customers, adoption, revenue, market size, user-study findings, time saved, verified deployment or live integrations. If asked about an unmeasured outcome, say it is the next thing to validate.') ,PageBreak()]

story += [para('1. Executive overview','H1x'),para('CollabDesk is a local-first creator-brand partnership workspace configured in this checkout for one demo creator, Aanya Kulkarni. It turns an inbound brand inquiry into a structured deal record, a transparent rate comparison, a reviewable response draft and visible follow-up stages. The creator remains in control of business decisions and outgoing messages.'),para('<b>Attraction:</b> find fit using creator context and content patterns. <b>Motion:</b> capture a brand email, structure its terms, compare the offer and draft a reply. <b>Transformation:</b> keep status and next steps visible so the creator can build a more manageable business workflow.'),para('Pitch in one sentence','H2x'),para('CollabDesk helps a creator make the business side of each brand inquiry easier to understand and act on, while keeping the creator in control.'),para('Concrete example','H2x'),para('Seed profile: Aanya is a Pune food and city-life creator with 48,000 demo followers and rates of INR 15,000 per reel, INR 8,000 per post and INR 4,000 for stories. Café Ramwadi offers INR 8,000 for one reel and two stories with 30-day usage. The prototype flags the offer below its 70% threshold of INR 10,500. These are fixture values, not market recommendations.'),para('2. Product and feature guide','H1x'),table([['View / feature','Purpose and interaction','Implementation and current boundary'],['Today','Action suggestions, counts and content context.','GET /api/today; suggestions only, not scheduled reminders.'],['Inbox','Paste or select an example email and parse it.','POST /api/inbox/parse; raw text is sent to OpenAI if configured. Fallback otherwise.'],['Deals','Board grouped as new, negotiating, confirmed, posted, paid.','GET/PATCH /api/deals; shared single-profile state.'],['Deal detail','Inspect terms/quote; draft accept, counter, decline or ask-brief.','POST rate/reply; edit and copy. Draft is not sent or saved as sent.'],['Content','Reach averages by topic from demo posts.','GET /api/content; fixture data, no social connection.'],['Media kit','Edit profile, niche, follower count and rates.','GET/PUT /api/creator; one shared demo profile.'],['Ask your desk','Bounded workspace questions about rates, follow-ups and post context.','POST /api/assistant; 8 requests/minute per client key; no data mutation.'],['Storage','Persist creator, deals[] and posts[].','JSON file default; optional Supabase adapter stores one state row.'],['Alternate TS engine','Helpers for parsing, quoting, reply and fit.','src/lib/collab/engine.ts is not imported by the active React/API workflow.']],[31*mm,64*mm,77*mm]),para('Rate rule in plain language','H2x'),para('Start with the creator rate for the selected format. More than 30 usage days adds 40%, rounded to the nearest INR 100. An offer below 70% of the suggested amount is flagged. For a 30-day INR 15,000 reel, the threshold is INR 10,500. At 60 days the suggested reel fee becomes INR 21,000. The code does not add fees for each deliverable.'),PageBreak(),para('3. Architecture, data and security boundaries','H1x'),para('<b>Frontend:</b> React 18 and Vite. src/App.jsx contains page routing and view components. src/api.js wraps API requests. Vite serves the UI on port 5173 and proxies /api to the API on port 3001. npm run build creates static assets in dist/.'),para('<b>API:</b> Node.js and Hono. server/index.js defines routes, validation, parsing, reply and assistant flow. server/rate.js contains deterministic quote and insight helpers. server/prompts.js defines prompts; server/llm.js calls OpenAI when enabled.'),para('<b>State:</b> server/data/db.json is the default. server/store.js serializes local mutations and replaces through a temporary file. Optional server/supabase-store.js stores the same JSON state in one collabdesk_state row and retries revision conflicts up to five times. It remains a single-profile shape, not a tenant model.'),para('<b>Security:</b> no login, authentication, authorization or per-user data boundary exists. Loopback binding and CORS are not identity controls. Keep the demo local; do not expose its API on a shared network. No email inbox, social accounts, publishing, invoices, payments or notifications are connected.'),para('4. Source code map','H1x'),table([['Area','Source / key behavior'],['UI + routes','src/App.jsx: routeFor, Inbox, Deals, DealDetail, Content, Kit, Today, DeskAssistant; src/main.jsx bootstraps.'],['Client API','src/api.js: browser fetch wrapper and endpoint methods.'],['Routes + validation','server/index.js: Hono routes, validParsedDeal, fallbackParse, fallbackReply, workspaceAssistant, assistant limits.'],['Pricing + insight','server/rate.js: quote(), insight(), todayActions().'],['Prompts + provider','server/prompts.js, server/llm.js: model instructions, JSON extraction, 10-second timeout.'],['Persistence','server/store.js, server/supabase-store.js, supabase/migrations/202610230001_collabdesk_state.sql.'],['Fixtures + tests','server/data/db.json, server/samples.js, test/.'],['Unwired prototype helpers','src/lib/collab/engine.ts and types.ts are not used by active UI/API.'],['Older audit','AUDIT.md predates the current UI; use current imports/routes and docs/architecture for present behavior.']],[38*mm,134*mm]),para('5. End-to-end request flows','H1x'),para('<b>Email -> deal:</b> Inbox calls api.js -> POST /api/inbox/parse. Server optionally sends raw email to the model, validates fields, falls back on provider error/timeout/invalid output, appends a new deal with status new and returns it. Sample fallback recognizes limited patterns; unknown text can become a generic record.'),para('<b>Quote:</b> Deal detail -> POST /api/deals/:id/rate -> quote() reads creator rate, format, usageDays and budgetInr. It calculates suggested fee and lowball flag in code. AI is not involved.'),para('<b>Reply:</b> UI selects intent -> POST /api/deals/:id/reply -> server computes fixed fee first, then optionally generates text. Fallback template is used if model unavailable. User edits/copies; no send endpoint.'),para('<b>Pipeline:</b> UI status action -> PATCH /api/deals/:id -> allowed status validation -> store update -> updated row returned. Today actions are derived suggestions.'),para('6. AI, privacy and automation','H1x'),table([['Action','Sent to model if enabled','Fallback / control'],['Email parse','Raw pasted email text.','Limited deterministic sample parser; validated record.'],['Reply draft','Deal fields, intent and fixed suggested fee; not raw email body.','Template text; amount is fixed by code.'],['Ask desk','Question plus bounded creator/deal/post summary; no raw email.','Deterministic workspace answers; no writes.'],['Quote','Nothing.','Always deterministic server-side rule.']],[30*mm,79*mm,63*mm]),para('Provider is optional OpenAI Chat Completions with gpt-4o-mini and a 10-second timeout. Missing key, provider failure, timeout or invalid output falls back. Assistant caps: 8 requests per minute per client key, question max 500 characters, answer max 500, up to three short suggestions. Model spend quotas are not implemented. Do not paste sensitive real correspondence into a public demo.'),para('7. Evidence and limitations','H1x'),bullets(['Automated backend suite: 10 passed, 0 failed; production Vite build passes.','20-slide PPTX export validated with 0 package/layout findings and first-party import passed.','Read-only UI inspection covered Today and Inbox. No parse was triggered against an existing server because its configured data path was unknown.','Not verified: browser end-to-end journey, accessibility, responsive behavior, live OpenAI, live Supabase app requests, deployment, user interviews or impact.','No measured time savings, revenue, adoption or conversion claims.','Content figures are fixtures: food average 78,000 across 3 posts; one beauty post 11,000. No platform analytics are connected.','The insight helper compares food and beauty only; do not claim commute category performance from that calculation.'])]

story += [para('8. Slide-by-slide speaker script','H1x'),para('Core pitch: slides 1-18, approximately 6-7 minutes. Slides 19-20 are optional technical backups. Each entry gives the point and a suggested line.'),table([['# / time','Point and suggested line'],['1 / 15s','Introduce CollabDesk: a creator-first desk for turning inbound inquiries into clear partnership decisions.'],['2 / 20s','The seeded Café Ramwadi offer is INR 8,000 against a demo reel rate of INR 15,000; this is an example, not a market statistic.'],['3 / 20s','An email starts more work: terms, decisions, replies and follow-through.'],['4 / 20s','Aanya’s demo profile supplies rates and usage guardrails for a consistent comparison.'],['5 / 20s','Email alone does not organize the workflow. This is a workflow framing, not competitor research or measured savings.'],['6 / 20s','Attraction finds fit, Motion moves the deal and Transformation makes next steps clearer.'],['7 / 20s','Name the five views: Today, Inbox, Deals, Content and Media Kit.'],['8 / 20s','Capture, structure, decide, respond and track; the creator reviews each decision.'],['9 / 25s','Show how the Café Ramwadi email becomes a deal card and counter draft. It does not auto-send.'],['10 / 25s','Explain INR 15,000 rate x 70% = INR 10,500 cutoff; INR 8,000 falls below it.'],['11 / 25s','AI can extract and draft; code controls the fee. Fallback keeps a no-key demo possible.'],['12 / 20s','Food fixtures average 78,000 across three posts; beauty is one post at 11,000. Not live analytics.'],['13 / 25s','Show React UI, Hono API and workspace store; disclose missing auth and social/email connections.'],['14 / 20s','One state document fits a one-profile prototype, not a multi-creator product.'],['15 / 25s','Input bounds and atomic writes support the local prototype but do not replace identity or access control.'],['16 / 20s','Ten tests and production build pass. User impact is still a hypothesis.'],['17 / 20s','Ask creators to test whether terms are clearer and next actions easier.'],['18 / 20s','Describe validation measures: time, extraction quality, confidence and follow-through. Ask for pilot partners.'],['19 / optional','Use the endpoint map only for a technical question; routes are shared demo routes.'],['20 / optional','Use the source map; disclose that alternate TypeScript helpers are not connected to the UI.']],[23*mm,149*mm]),para('9. Safe live demo plan','H1x'),para('Use a temporary database copy, and do not start another process if ports 5173 or 3001 are already occupied. Node.js 20 or later is needed.'),para('<font name="Courier">cp server/data/db.json /tmp/collabdesk-demo.json<br/>COLLABDESK_DB_PATH=/tmp/collabdesk-demo.json npm run dev</font><br/><br/>Open http://127.0.0.1:5173. Vite proxies API calls to port 3001.'),bullets(['Today: point to suggested reply and payment follow-up.','Inbox: select Café Ramwadi sample and click Parse email. With no key, explain deterministic fallback.','Open the deal: show offer, reel rate and usage terms.','Show the quote: INR 8,000 compared with INR 15,000, below INR 10,500 threshold.','Choose Counter, edit the draft and copy it. Emphasize it is not sent.','Optionally move status to Negotiating; confirm the board updates.','Use only seeded or consented non-sensitive data. Stop local services afterward; the seed file is untouched when the temp path is set.']),para('Expected result','H2x'),para('The parser creates a deal, deterministic pricing flags the example and the counter draft includes the calculated fee. Extraction details vary with model configuration and fallback pattern recognition.'),para('10. Judge Q&A: 30 grounded answers','H1x')]
qas=[
('1. What problem are you solving?','Creators must extract terms, compare rates, reply and track next steps across brand messages. The prototype puts those steps into one reviewable workspace.'),
('2. Who is the first user?','The demo is configured for one creator. The intended pilot user is a creator handling inbound brand partnerships; segment fit is not yet validated.'),
('3. What does Attraction -> Motion -> Transformation mean?','Find fit, move an inquiry through structured decisions, then make business follow-through clearer. The strongest current implementation is the inbox-to-deal loop.'),
('4. Is INR 8,000 market data?','No. It is a seeded sample email used to demonstrate the calculation.'),
('5. How is the suggested rate calculated?','Start with the selected format rate; more than 30 usage days adds 40%, rounded to INR 100. Deliverables are not separately priced.'),
('6. Define lowball.','An offer under 70% of suggested fee is flagged. At INR 15,000, 30-day reel rate, threshold is INR 10,500.'),
('7. Is that fair to every creator?','No benchmark is claimed. It is a creator-editable rule; fairness and outcomes need pilot evidence.'),
('8. What does AI do?','Optional extraction, reply wording and bounded questions. It does not set price or send messages.'),
('9. What if no key is configured?','Deterministic sample parsing, reply templates and workspace answers are used.'),
('10. Which model?','Optional OpenAI Chat Completions, gpt-4o-mini, with a 10-second timeout. Live provider configuration was not verified.'),
('11. Is email data sent?','Raw email goes to OpenAI for parsing if configured. Reply uses deal facts, not original body. Assistant context excludes raw email.'),
('12. Does it send a counter?','No. It returns a draft for review, edit and copy; no email-sending route exists.'),
('13. What is integrated?','Local frontend/API path and optional model code. No connected inbox, social, calendar, payment or publishing service.'),
('14. Are metrics live?','No. Post metrics are fixtures; there is no social platform connection.'),
('15. What does content show?','Three seeded food posts average 78,000 reach; one beauty post has 11,000. It is a tiny directional fixture set.'),
('16. Why a JSON document?','It keeps a one-profile prototype inspectable. Multi-creator use needs identity and ownership design.'),
('17. Why optional Supabase?','It can store the same state in one JSONB row and checks revisions to avoid lost updates. Live app configuration was not checked.'),
('18. Is this ready for public use?','No. Authentication, authorization and user isolation are absent. Keep it local.'),
('19. What do CORS and loopback do?','They constrain origin and default listen address, not user identity or authorization.'),
('20. What is tested?','10 backend tests cover routes, validation, fallback, pricing, assistant limits and mocked Supabase; Vite build passes.'),
('21. Was browser E2E verified?','No automated browser journey. UI was inspected read-only; API tests and production build passed.'),
('22. What results do you have?','No measured time savings, revenue, adoption, conversion or user-study results yet.'),
('23. How will you validate value?','Pilot with creators and measure time to reviewed reply, extraction accuracy, clarity/confidence and next-action completion.'),
('24. Biggest technical risk?','No identity or private workspace boundaries. Secure authentication and per-user data isolation come before shared deployment.'),
('25. Biggest product risk?','Different creators have distinct rates and negotiation practices. Keep creator control and test rules before automating more.'),
('26. Business model?','Not defined or validated in the repository. The current ask is pilot validation.'),
('27. What is the moat?','No moat is demonstrated. The current differentiator is a transparent creator-controlled workflow idea that needs comparison and validation.'),
('28. How do you handle extraction errors?','Validate allowed fields, fall back on errors and present the result for creator review against the source email.'),
('29. Why not fully automate negotiation?','Pricing and acceptance belong to the creator. Drafting repetitive language can help while the creator decides and sends.'),
('30. What is your ask?','Creator pilot partners and candid feedback on inbox-to-reply clarity, plus a few brand perspectives on how terms arrive.')]
for q,a in qas: story += [KeepTogether([para(q,'Q'),para(a,'A')])]
story += [para('11. Technical backup and validation','H1x'),table([['Route','Purpose'],['GET /api/health','Health check.'],['GET/PUT /api/creator','Read/update profile and rate card.'],['GET /api/deals; GET /api/deals/:id','List and read deal details.'],['PATCH /api/deals/:id','Update deal status.'],['GET /api/samples','Read sample emails.'],['POST /api/inbox/parse','Parse email and create deal.'],['POST /api/deals/:id/rate','Calculate quote.'],['POST /api/deals/:id/reply','Generate response draft.'],['GET /api/content; GET /api/today','Fixture insight and action suggestions.'],['POST /api/assistant','Bounded workspace question.']],[78*mm,94*mm]),para('Engineering notes','H2x'),bullets(['API body cap: 16 KB; email text cap: 10,000 characters.','File mutations serialize in-process and use temp file plus atomic rename. Supabase optimistic revision update retries up to five times.','Assistant limit is in-memory by client key; not a distributed quota.','Vercel-style adapters exist under api/, but deployment was not verified.','Alternate TypeScript engine is unconnected and not part of active product behavior.']),para('12. Last-minute revision sheet','H1x'),table([['Prompt','Remember'],['Pitch','Creator-first workspace for inbound brand partnership decisions.'],['Problem','Scattered terms create extraction, pricing, reply and follow-up work.'],['Solution','Capture -> structure -> compare -> draft -> track; human decides.'],['Three features','Email-to-deal, deterministic rate/usage quote, editable draft and pipeline.'],['Stack','React/Vite; Node/Hono; JSON default; optional Supabase/OpenAI.'],['Demo math','INR 15,000 reel; INR 8,000 seeded offer; INR 10,500 cutoff.'],['Evidence','10/10 tests and build pass; no browser E2E or impact data.'],['Limit','Single shared profile, no auth; local demo only.'],['Ask','Creator pilot partners; feedback on clarity and follow-through.'],['Close','Make the business side of creator work easier to manage.']],[42*mm,130*mm]),para('Safe closing line','H2x'),para('CollabDesk has a working prototype for turning an inbound inquiry into a structured, priced and reviewable next step. Backend checks and the production build pass; the next proof is whether creators find the workflow clearer and more useful in a consented pilot.')]
doc=SimpleDocTemplate(OUT,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=17*mm,bottomMargin=19*mm,title='CollabDesk Hackathon Presentation Guide',author='CollabDesk project team')
story = [item for block in story for item in (block if isinstance(block,list) else [block])]
doc.build(story,onFirstPage=foot,onLaterPages=foot)
print(OUT)
